// === Tab: mySketch.js ===
/* Flower Dance animation using Lygia library

I am actually not sure how much the animation is reacting to the sound. You could certainly 
amp it up by editing line 101.

References:
https://github.com/patriciogonzalezvivo/lygia
https://github.com/patriciogonzalezvivo/lygia_examples/blob/main/draw_shapes.frag
https://thecodingtrain.com/tracks/sound

Song Credit:
Summer Adventures by SergePavkinMusic 
https://pixabay.com/music/search/?order=ec&pagi=5
*/

let theShader;
let fft;
const smoothing = 0.8; // play with this, between 0 and .99
const binCount = 64; // size of resulting FFT array. Must be a power of 2 between 16 and 1024

let volume = 0.01; // initial starting volume of amplitude (necessary for p5.sound)
let amplitude;
let song;
let img;
let noise;
let mic;
let shdr;
let vertSource, fragSource;
let button;
let smoothTreble = 0;
let alpha = 0.5; // smoothing factor
let trebleSmoothing = 0.05; // 0.05 = very smooth, 0.2 = more responsive

function preload() {
	song = loadSound("https://openprocessing.org/sketch/2681583/files/summer-adventures-115949.mp3");
	vertSource = loadStrings("https://openprocessing.org/sketch/2681583/files/vertex.glsl");
	fragSource = loadStrings("https://openprocessing.org/sketch/2681583/files/fragment.glsl");
}

function toggleSong() {
	if (song.isPlaying()) {
		song.pause();
	} else {
		song.play();
	}
}

function setup() {
	let canvasSize = min(windowWidth - 30, windowHeight - 30)
	let canvas = createCanvas(windowWidth, windowHeight, WEBGL);
	//canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);
	pixelDensity(1);
	noCursor();

	// LYGIA code
	vertSource = resolveLygia(vertSource);
	fragSource = resolveLygia(fragSource);

	// Hi There! this ^ two lines ^ use `resolveLygia( ... )` to resolve the LYGIA dependencies from the preloaded `shader.vert` and `shader.frag` files.
	// Check `index.html` to see how it's first added to the project.
	// And then, the `shader.frag` file to how it's used.

	theShader = createShader(vertSource, fragSource);

	blob0 = new Particle(0, 0);
	blob1 = new Particle(100, 50);
	button = createButton("Play Song");
	button.mousePressed(toggleSong);
	button.position(10, 10);
	song.play();

	// initialize the FFT, plug in our variables for smoothing and binCount
	fft = new p5.FFT(smoothing, binCount);
	//peakDetect = new p5.PeakDetect();

	amplitude = new p5.Amplitude();
	fft.setInput(song);

	// If you want to use mic instead
	// mic = new p5.AudioIn();
	// mic.start();
	//fft.setInput(mic);
}

function draw() {
	background(0);
	let spectrum = fft.analyze(binCount);
	//peakDetect.update(fft);
	//https://p5js.org/reference/p5.FFT/getEnergy/
	const bass = fft.getEnergy("bass");
	const mid = fft.getEnergy("mid");
	const high_mid = fft.getEnergy("highMid");
	const treble0 = fft.getEnergy("mid", "treble");
	const treble = fft.getEnergy("treble") / 255.0;
	//smoothTreble = lerp(smoothTreble, treble, alpha);
	let vol = amplitude.getLevel();

	//console.log(mid);
	// let mapMid;
	// if ( peakDetect.isDetected ) {
	//   mapMid = map(mid, 0, 255, 0.0, 0.5); //.25
	// } else {
	//   mapMid = map(mid, 0, 255, 0.5, 1.);
	// }
	//console.log(vol)
	const mapMid = map(mid, 0, 255, 0., 1.);
	const mapHighMid = map(high_mid, 0, 255, 0., 1.);
	const mapVol = map(volume, 0, 0.40, 0.0, 1.0);
	const mapBass = map(bass, 0, 255, 0.4, 0.6);
	//const mapTreble = fft.getEnergy("treble") / 255.0; // normalize 0–1 
	// Exponential smoothing (lerp style)
	smoothTreble = lerp(smoothTreble, treble, trebleSmoothing);
	theShader.setUniform("u_vol", mapVol);
	theShader.setUniform("u_bass", mapBass);
	theShader.setUniform("u_mid", mapMid);
	theShader.setUniform("u_hmid", mapHighMid);
	theShader.setUniform("u_treble", smoothTreble);
	theShader.setUniform("u_blob0", [blob0.x, blob0.y]);
	theShader.setUniform("u_blob1", [blob1.x, blob1.y]);
	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	theShader.setUniform("u_time", millis() / 1000.0);

	shader(theShader);

	// rect gives us some geometry on the screen
	rect(0, 0, width, height);
	blob0.update();
	blob1.update();
}

// === Tab: particle.js ===
class Particle {
  constructor(x,y) {
    this.x = x;
    this.y = y;
    this.vx = random(-2,2);
    this.vy = random(-2,2);
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    if (this.x > width || this.x < 0) this.vx *= -1;
    if (this.y > height || this.y < 0) this.vy *= -1;
  }


}

// === Tab: fragment.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

// Pass in uniforms from the sketch.js file
uniform vec2 u_resolution; 
uniform float u_time;
uniform vec2 u_mouse;
uniform float u_vol;
uniform float u_bass;
uniform float u_mid;
uniform float u_hmid;
uniform float u_treble;
uniform vec2 u_blob0;
uniform vec2 u_blob1;

// Add path to Lygia functions
#include "lygia/generative/curl.glsl"
#include "lygia/sdf/flowerSDF.glsl"
#include "lygia/math/smootherstep.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/space/hexTile.glsl"
#include "lygia/space/scale.glsl"

void main()
{
	vec2 uv = (gl_FragCoord.xy-0.5*u_resolution.xy)/u_resolution.y;
    vec2 blob0_uv = u_blob0.xy /  u_resolution.xy;
    vec2 blob1_uv = u_blob1.xy /  u_resolution.xy;
	  vec2 pixel = 1.0/u_resolution;
    float t = u_time*0.1;
    vec2 st = uv * rotate2d(t);  // add rotation
	  vec2 mo = u_mouse.xy/u_resolution.xy;
    vec4 color = vec4(vec3(0.0), 1.0);

    vec2 diff0 = st.xy - blob0_uv.xy;
    vec2 diff1 = st.xy - blob1_uv.xy;
    float d0 = length(diff0);
    vec4 hc1 = hexTile(diff0*4.0);
    vec4 hc2 = hexTile(diff1*4.0);

    float c;
    for (int y = -1; y < 1; y++){ 
        for (int x = -1; x < 1; x++){ 
        vec2 offs = vec2(x,y);
				// Can substitute other shapes
				// https://github.com/patriciogonzalezvivo/lygia_examples/blob/main/draw_shapes.frag
				//float d1 = flowerSDF(hc1.xy- offs- vec2(u_treble), 6);
        //float d2 = flowerSDF(hc2.xy- offs, 6) - 0.1;

				float eased = smootherstep(0.0, 1.0, u_treble);
      	float d1 = flowerSDF(hc1.xy - offs - vec2(eased), 6);
				float d2 = flowerSDF(hc2.xy - offs, 6);

				//float eased = smootherstep(0.0, 1., u_treble);
        //float d = mix(d1, d2, eased);

				//float d = mix(d1, d2, u_treble);


				//float d = mix(d1, d2, u_treble);

				float d = mix(d1, d2, 0.5);
		   // float tBlend = smoothstep(0.0, 1.0, smoothTreble); 
       // float d = mix(d1, d2, tBlend);
        c = smootherstep( .05, 0.01, d*sin(hc1.x*hc1.x+u_time));
        }
    }

    vec3 d3 = curl(vec3(st * 2.0, 0.2*u_time)) * 0.5 + 0.5;

    color.rgb = mix(d3, vec3(0.0), c); // black
    gl_FragColor = color;
}

// === Tab: vertex.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;

  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}

